window.createGroundBossBehavior=function({W,H,random,player,fire,missile}) {
  function protectedDenim(e,units){return !!e.chief&&units.some(u=>!u.chief&&(u.hp>0||u.geneRecovering||u.geneDisabled&&!u.retreated));}
  function aim(e){const p=player();return {x:p.x,y:p.y};}
  function windup(e){e.bossMode='windup';e.bossClock=.6;e.slashTarget=aim(e);e.shielding=false;}
  function slash(e,dt){e.bossClock-=dt;if(e.bossMode==='windup'&&e.bossClock<=0){const p=e.slashTarget,a=Math.atan2(p.y-e.y,p.x-e.x);e.slashVx=Math.cos(a)*600;e.slashVy=Math.sin(a)*600;e.bossMode='slash';e.bossClock=.42;}else if(e.bossMode==='slash'){e.x=Math.max(65,Math.min(W-65,e.x+e.slashVx*dt));e.y=Math.max(80,Math.min(H-80,e.y+e.slashVy*dt));if(e.bossClock<=0){e.bossMode='recover';e.bossClock=e.furyMode?1.1:.8;}}else if(e.bossMode==='recover'&&e.bossClock<=0){e.bossMode=null;e.moveClock=0;if(e.chief){if(e.furyMode)windup(e);else{e.bossMode='shield';e.bossClock=e.enraged?1.4:2.1;e.shielding=true;}}}}
  function roam(e,dt,speed){e.moveClock=(e.moveClock||0)-dt;if(e.goalX===undefined||e.moveClock<=0||Math.hypot(e.goalX-e.x,e.goalY-e.y)<20){e.goalX=random(160,W-95);e.goalY=random(100,H-100);e.moveClock=random(.45,1.25);e.roamSpeed=random(speed*.8,speed*1.2);}const dx=e.goalX-e.x,dy=e.goalY-e.y,d=Math.hypot(dx,dy),step=Math.min(d,e.roamSpeed*dt);if(d){e.x+=dx/d*step;e.y+=dy/d*step;}}
  function update(e,dt,units){if(e.conversationHold){e.burstLeft=0;return;}if(e.conversationGoal){e.burstLeft=0;const p=e.conversationGoal,dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy),step=Math.min(Math.max(0,d-85),340*dt);if(d>0){e.x+=dx/d*step;e.y+=dy/d*step;}e.conversationArrived=d<=90;return;}if(e.chief&&e.furyMode){slash(e,dt);return;}const oldX=e.x;if(!e.chief&&!e.bossMode){e.singleShotClock=(e.singleShotClock??.7)-dt;if(e.singleShotClock<=0&&e.x<W-30&&e.x>20){fire(e.x-22,e.y,220);e.singleShotClock=random(e.enraged?.25:.4,e.enraged?.4:.6);}}
    if(e.chief){if(protectedDenim(e,units)){e.shielding=false;e.bossMode=null;roam(e,dt,280);}else{if(!e.denimUnlocked){e.denimUnlocked=true;e.burstLeft=0;e.bossMode='shield';e.bossClock=e.enraged?1.4:2.1;}if(e.bossMode==='shield'){e.shielding=true;roam(e,dt,175);e.bossClock-=dt;if(e.bossClock<=0)windup(e);}else slash(e,dt);}}
    else {e.shielding=false;if(e.bossMode)slash(e,dt);else roam(e,dt,360);}
    if(e.x>oldX+.01&&!e.bossMode)e.retreat=.08;
  }
  function attack(e,units){if(e.bossMode)return;if(e.chief){if(!protectedDenim(e,units))return;e.shot=e.enraged?.4:.65;fire(e.x-22,e.y,220);return;}e.shot=random(e.enraged?1.1:1.8,e.enraged?1.8:2.6);const choices=['missile','slash'].filter(a=>a!==e.lastBossAttack),kind=choices[Math.floor(random(0,choices.length))];e.lastBossAttack=kind;if(kind==='missile'){missile(e);}else windup(e);}
  return {protectedDenim,update,attack};
};

