function zakuDestroySound(){if(muted)return;duckBgm();if(playSfx('zaku'))return;try{audio??=window.GameSound?.context()||new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;if(now-lastZakuSound<.035)return;lastZakuSound=now;for(const [offset,high,low,duration,volume] of [[0,1800,240,.095,.17],[.07,1250,110,.12,.13]]){const start=now+offset,osc=audio.createOscillator(),gain=audio.createGain(),filter=audio.createBiquadFilter();osc.type='triangle';osc.frequency.setValueAtTime(high,start);osc.frequency.exponentialRampToValueAtTime(low,start+duration);filter.type='lowpass';filter.frequency.setValueAtTime(3600,start);gain.gain.setValueAtTime(.001,start);gain.gain.linearRampToValueAtTime(volume,start+.003);gain.gain.exponentialRampToValueAtTime(.001,start+duration);osc.connect(filter);filter.connect(gain);gain.connect(audio.destination);osc.start(start);osc.stop(start+duration+.005)}}catch{}}
function explosionSound(big=false){if(muted)return;duckBgm(big?1:.65);if(playSfx('explosion'))return;try{audio??=window.GameSound?.context()||new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;if(now-lastExplosionSound<.045)return;lastExplosionSound=now;const duration=big?.24:.16;if(!explosionNoise){explosionNoise=audio.createBuffer(1,Math.ceil(audio.sampleRate*.3),audio.sampleRate);const data=explosionNoise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.8;}const noise=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();noise.buffer=explosionNoise;filter.type='bandpass';filter.Q.setValueAtTime(.65,now);filter.frequency.setValueAtTime(2600,now);filter.frequency.exponentialRampToValueAtTime(240,now+duration);gain.gain.setValueAtTime(.001,now);gain.gain.linearRampToValueAtTime(big?.22:.16,now+.004);gain.gain.exponentialRampToValueAtTime(.001,now+duration);noise.connect(filter);filter.connect(gain);gain.connect(audio.destination);noise.start(now);noise.stop(now+duration);const body=audio.createOscillator(),bodyGain=audio.createGain();body.type='triangle';body.frequency.setValueAtTime(big?180:230,now);body.frequency.exponentialRampToValueAtTime(55,now+.11);bodyGain.gain.setValueAtTime(big?.18:.13,now);bodyGain.gain.exponentialRampToValueAtTime(.001,now+.13);body.connect(bodyGain);bodyGain.connect(audio.destination);body.start(now);body.stop(now+.14);}catch{}}
