function decodeImage(im){if(typeof setTimeout!=='function')return im.decode();return new Promise((resolve,reject)=>{let settled=false;const finish=err=>{if(settled)return;settled=true;clearTimeout(timer);im.removeEventListener?.('load',loaded);im.removeEventListener?.('error',failed);err?reject(err):resolve();},loaded=()=>finish(),failed=()=>finish(new Error('画像を取得できません'));const timer=setTimeout(()=>finish(new Error('読み込みが30秒間完了しません')),30000);im.addEventListener?.('load',loaded,{once:true});im.addEventListener?.('error',failed,{once:true});if(im.complete&&im.naturalWidth>0){finish();return;}im.decode().then(()=>finish()).catch(err=>{if(im.complete)finish(err);});});}
