async function load(name,path){const im=new Image();im.src=path;await decodeImage(im);const measured=window.GameSpriteMetadata?.singles[path];if(measured){images[name]={im,...measured};return;}const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d');g.drawImage(im,0,0);const data=g.getImageData(0,0,c.width,c.height).data;let l=c.width,t=c.height,r=0,b=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(data[(y*c.width+x)*4+3]>35){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y)}images[name]={im,sx:l,sy:t,sw:r-l+1,sh:b-t+1};c.width=c.height=1;}
async function loadGroundSheet(prefix,path,cols,rows){const im=new Image();im.src=path;await decodeImage(im);const measured=window.GameSpriteMetadata?.sheets[path];if(measured){measured.forEach((f,i)=>images[prefix+i]={im,...f});return;}const canvas=document.createElement('canvas');canvas.width=im.width;canvas.height=im.height;const q=canvas.getContext('2d');q.drawImage(im,0,0);const pixels=q.getImageData(0,0,im.width,im.height).data;for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const x0=Math.floor(col*im.width/cols),x1=Math.floor((col+1)*im.width/cols),y0=Math.floor(row*im.height/rows),y1=Math.floor((row+1)*im.height/rows);let l=x1,r=x0,t=y1,b=y0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(pixels[(y*im.width+x)*4+3]>100){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}let bodyTop=t;if(prefix==='groundZakuAction'&&[4,5].includes(row*cols+col)){bodyTop=b;for(let y=t;y<=b;y++)for(let x=l;x<=r;x++){const i=(y*im.width+x)*4;if(pixels[i+3]>160&&pixels[i+1]>pixels[i]*1.06&&pixels[i+1]>pixels[i+2]*1.2&&pixels[i+1]>45)bodyTop=Math.min(bodyTop,y);}}images[prefix+(row*cols+col)]={im,sx:l,sy:t,sw:Math.max(1,r-l+1),sh:Math.max(1,b-t+1),bodyHeight:bodyTop<b?b-bodyTop+1:Math.max(1,b-t+1)};}canvas.width=canvas.height=1;}
// Split the three opaque character silhouettes, so a hand/boot near a cell
// boundary is preserved instead of clipping at an assumed equal-width grid.
async function loadFederationCrew(path){
 const im=new Image();im.src=path;await decodeImage(im);
 const sheet=document.createElement('canvas');sheet.width=im.width;sheet.height=im.height;
 const q=sheet.getContext('2d');q.drawImage(im,0,0);
 const pixels=q.getImageData(0,0,im.width,im.height),data=pixels.data,n=im.width*im.height;
 const labels=new Int32Array(n),queue=new Int32Array(n),parts=[];let id=0;
 for(let start=0;start<n;start++){
  if(labels[start]||data[start*4+3]<=100)continue;
  id++;let head=0,tail=1,l=im.width,r=0,t=im.height,b=0;queue[0]=start;labels[start]=id;
  while(head<tail){const p=queue[head++],x=p%im.width,y=Math.floor(p/im.width);l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);
   for(const next of [x>0?p-1:-1,x<im.width-1?p+1:-1,y>0?p-im.width:-1,y<im.height-1?p+im.width:-1])if(next>=0&&!labels[next]&&data[next*4+3]>100){labels[next]=id;queue[tail++]=next;}
  }
  parts.push({id,area:tail,l,r,t,b});
 }
 const chosen=parts.sort((a,b)=>b.area-a.area).slice(0,3).sort((a,b)=>a.l-b.l);
 for(let i=0;i<chosen.length;i++){
  const p=chosen[i],sprite=document.createElement('canvas');sprite.width=p.r-p.l+1;sprite.height=p.b-p.t+1;
  const g=sprite.getContext('2d'),out=g.createImageData(sprite.width,sprite.height);
  for(let y=0;y<sprite.height;y++)for(let x=0;x<sprite.width;x++){const index=(y+p.t)*im.width+x+p.l;if(labels[index]!==p.id)continue;const to=(y*sprite.width+x)*4;for(let c=0;c<4;c++)out.data[to+c]=data[index*4+c];}
  g.putImageData(out,0,0);images['federationCrew'+i]={im:sprite,sx:0,sy:0,sw:sprite.width,sh:sprite.height};
 }
 sheet.width=sheet.height=1;
}

function groundSuit(name){const frame=Math.floor(time/.09)%8;if(name.startsWith('gundam')){const action={gundam:2,gundamUnarmed:0,gundamVulcan:7,gundamBazooka:6,gundamDual:6,gundamBack:10,gundamSaberReady:4,gundamSaberSlash:5}[name];return ['gundamUnarmed'].includes(name)?'groundGundamRun'+frame:'groundGundamAction'+(action??0);}if(name==='zakuMissile')return 'groundZakuAction8';if(name==='zakuHawkReady')return 'groundZakuAction4';if(name==='zakuHawkSlash')return 'groundZakuAction5';if(name==='zakuShield')return 'groundZakuAction3';if(name==='zakuBack')return 'groundZakuAction10';if(name==='zaku')return 'groundZakuRun'+frame;return name;}
function sprite(name,x,y,w,alpha=1){if(name.startsWith('javelinArt')){weaponArt.drawSuit(name,x,y,65*images.zaku.sh/images.zaku.sw*(groundStage?1.28:1),alpha,150+35*lv('javelinLength'));return;}if(groundStage&&(name==='gundam'||name==='gundamBack'&&player?.laser)&&images.rifleWalk0){weaponArt.drawSuit('rifleWalk'+(Math.floor(time/.09)%8),x,y,65*images.zaku.sh/images.zaku.sw*1.28,alpha);return;}if(groundStage&&(name.startsWith('gundam')||['zaku','zakuShield','zakuBack','zakuHawkReady','zakuHawkSlash','zakuMissile'].includes(name))){const original=images[name],mapped=groundSuit(name),frame=images[mapped],base=images[name.startsWith('gundam')?'groundGundamAction0':'groundZakuAction0'];if(original&&frame&&base){const gundam=name.startsWith('gundam'),height=65*images.zaku.sh/images.zaku.sw*(gundam?1.28:1.23);w=height/(gundam?base.sh:(frame.bodyHeight||frame.sh))*frame.sw;y+=height/2-w*frame.sh/frame.sw/2;name=mapped;}}const a=images[name];if(!a)return;if(groundStage&&/^(gundam|zaku|char|gm|ball|guncannon|guntank)/.test(name)){ctx.save();ctx.globalAlpha=alpha*.25;ctx.fillStyle='#142317';ctx.beginPath();ctx.ellipse(x,y+w*a.sh/a.sw*.42,w*.42,5,0,0,Math.PI*2);ctx.fill();ctx.restore();}ctx.save();ctx.globalAlpha=alpha;ctx.imageSmoothingEnabled=false;ctx.drawImage(a.im,a.sx,a.sy,a.sw,a.sh,x-w/2,y-w*a.sh/a.sw/2,w,w*a.sh/a.sw);ctx.restore();}
