function equipmentMax(i){if(!player)return false;const key=custom.order[i];return {speed:player.speed>=4,spread:player.spread&&(!player.laser||lv('vulcanMix')>0),bazooka:player.missile&&!player.laser,rifle:player.laser,hammer:player.hammer,javelin:player.javelin,option:player.options>=4,barrier:player.shield>=3,evolve:player.evolved}[key]||false;}
