function loseLatestEquipment(){const history=player.equipmentHistory||[];while(history.length){const entry=history.pop(),k=entry.key,active=k==='speed'?player.speed>0:k==='option'?player.options>0:k==='barrier'?player.shield>0:k==='rifle'?player.laser:k==='bazooka'?player.missile:k==='spread'?player.spread:player[k==='evolve'?'evolved':k];if(!active)continue;if(k==='speed')player.speed=Math.max(0,player.speed-1);else if(k==='option'){player.options=Math.max(0,player.options-1);if(player.options<4)player.evolved=false;}else if(k==='barrier')player.shield=0;else Object.assign(player,entry.before);optionClocks=[0,0,0,0];updateCombatStrength();return k;}updateCombatStrength();return null;}
function upgrade(){if(state!=='playing'||launch||groundBossIntro?.active||selection<0||equipmentMax(selection)||!equipmentAvailable(selection))return;const key=custom.order[selection],voice={speed:0,bazooka:1,rifle:3,option:4,barrier:5,evolve:7}[key];const fields={speed:['speed'],spread:['spread','laser','missile','double'],bazooka:['spread','laser','missile','double'],rifle:['spread','laser','missile','double'],hammer:['hammer'],javelin:['javelin'],option:['options'],barrier:['shield'],evolve:['evolved']}[key],before=Object.fromEntries(fields.map(field=>[field,player[field]]));switch(key){case 'speed':player.speed=Math.min(4,player.speed+1);break;case 'spread':player.spread=true;if(!lv('vulcanMix'))player.laser=false;break;case 'bazooka':player.missile=true;player.double=true;player.laser=false;break;case 'rifle':player.laser=true;player.missile=false;player.double=false;break;case 'hammer':player.hammer=true;break;case 'javelin':player.javelin=true;break;case 'option':player.options=Math.min(4,player.options+1);break;case 'barrier':player.shield=3;break;case 'evolve':player.evolved=true;optionClocks=[0,0,0,0];break;}(player.equipmentHistory||=[]).push({key,before});updateCombatStrength();selection=-1;if(!muted&&!playSfx('equip'))tone(1100,.16,'triangle');if(!muted&&voice!==undefined)announceEquipment(voice);hud();}
function explode(x,y,color='#ffaa64',n=18,sound='explosion'){explosionSprites.push({x,y,age:0,size:n>=50?180:n>=24?100:65});for(let i=0;i<Math.min(n,8);i++)particles.push({x,y,vx:rand(-180,180),vy:rand(-180,180),life:rand(.25,.7),color,r:rand(2,6)});shake=Math.max(shake,5);if(sound==='zaku'||sound==='suit')zakuDestroySound();else if(sound==='ship'){if(!muted){duckBgm(1.6);if(!playSfx('ship'))explosionSound(true)}}else if(sound!=='silent')explosionSound(n>=60);}
