function updateWrecks(dt){for(const w of wrecks){w.age+=dt;if(!w.burst&&w.age>=w.duration){w.burst=true;explode(w.x,w.y,'#ffaf63',26,'silent');if(w.explosionDuration){const blast=explosionSprites[explosionSprites.length-1];blast.duration=w.explosionDuration;if(w.openBreach){blast.size=460;blast.breachBlast=true;for(let i=0;i<5;i++)explosionSprites.push({x:w.x+Math.cos(i*2.4)*75,y:w.y+Math.sin(i*2.4)*45,age:-i*.18,duration:2.6,size:170+i*15,breachBlast:true});shake=Math.max(shake,18);}}if(w.openBreach&&!colonyBreach)createColonyBreach(w.x,w.y);if(w.geneExplosion&&!muted)playSfx('geneExplosion',true);}}wrecks=wrecks.filter(w=>w.age<w.duration+(w.explosionDuration||.65));}
function hit(damage=25,barrierCost=1){if(player.dying>0||player.inv>0||$('training').checked)return;if(player.shield>0){player.shield=Math.max(0,player.shield-barrierCost);player.inv=1;explode(player.x,player.y,'#78efff',10);hud();return;}player.hp=Math.max(0,player.hp-damage);player.inv=1;if(player.hp>0){explode(player.x,player.y,'#ff8877',8,'silent');hud();return;}destroySuit(player.backBoost>0?'gundamBack':'gundam',player.x,player.y);loseLatestEquipment();lives--;player.dying=.48;player.inv=3;releaseTouch();keys.clear();hud();}
function sparkPaths(seed,tick,height){let value=(Math.floor(seed*10000)^Math.imul(tick+1,2654435761))>>>0;const random=()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296};const paths=[];if(random()<.16)return paths;const count=1+Math.floor(random()*3);for(let i=0;i<count;i++){let x=(random()-.5)*height*.95,y=(random()-.5)*height*.75;const points=[[x,y]],angle=random()*Math.PI*2,length=height*(.22+random()*.65),steps=3+Math.floor(random()*4);for(let k=1;k<=steps;k++){const jitter=(random()-.5)*height*.25;x+=Math.cos(angle)*length/steps-Math.sin(angle)*jitter;y+=Math.sin(angle)*length/steps+Math.cos(angle)*jitter;points.push([x,y])}paths.push(points);if(random()<.45){const origin=points[1+Math.floor(random()*(points.length-2))],branch=[origin];let bx=origin[0],by=origin[1];const direction=angle+(random()<.5?-1:1)*(.6+random());for(let k=0;k<2+Math.floor(random()*2);k++){bx+=Math.cos(direction)*height*.13+(random()-.5)*height*.14;by+=Math.sin(direction)*height*.13+(random()-.5)*height*.14;branch.push([bx,by])}paths.push(branch)}}return paths;}
function drawExplosionSprites(){const atlas=images.explosionAtlas;if(!atlas)return;ctx.save();ctx.globalCompositeOperation='lighter';ctx.imageSmoothingEnabled=false;for(const e of explosionSprites){if(e.age<0)continue;const frame=Math.min(14,1+Math.floor(e.age/(e.duration||.7)*14));ctx.drawImage(atlas.im,(frame%8)*64,Math.floor(frame/8)*64,64,64,e.x-e.size/2,e.y-e.size/2,e.size,e.size);}ctx.restore();}
function drawWrecks(){for(const w of wrecks){if(w.burst)continue;const im=images[w.suit];sprite(w.suit,w.x+Math.sin(w.age*95)*1.2,w.y,w.height*im.sw/im.sh,.9);const tick=Math.floor(w.age*26);ctx.save();ctx.translate(w.x,w.y);ctx.lineJoin='miter';ctx.lineCap='round';for(const points of sparkPaths(w.seed,tick,w.height)){ctx.beginPath();ctx.moveTo(...points[0]);for(const p of points.slice(1))ctx.lineTo(...p);ctx.shadowColor='#46dcff';ctx.shadowBlur=5;ctx.strokeStyle='#69d9ff';ctx.lineWidth=1.1;ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#edffff';ctx.lineWidth=.45;ctx.stroke()}ctx.restore();}}
