function terrainFloor(){return terrainFloorY;}
function measureTerrainFloor(){const mobile=window.matchMedia?.('(max-width:900px), (any-pointer:coarse)').matches,landscape=window.matchMedia?.('(orientation:landscape)').matches;if(!mobile||!landscape)return H;const height=canvas.getBoundingClientRect().height;return height>0?H-Math.min(H*.3,64*H/height):H;}
function terrain(wx,top=false){const floor=terrainFloor();if(groundStage)return groundStage.boundary(wx,top,floor);if(wx<1950||wx>10150)return top?0:floor;const fade=Math.min(1,(wx-1950)/450,(10150-wx)/450);const depth=50+12*Math.sin(wx/250)+8*Math.sin(wx/83);return top?depth*fade:floor-depth*fade;}
function surfaceBounds(x,halfWidth=24,halfHeight=24){let ceiling=0,floor=terrainFloor();if(terrainActive()){for(const offset of [-halfWidth,0,halfWidth]){ceiling=Math.max(ceiling,terrain(scroll+x+offset,true));floor=Math.min(floor,terrain(scroll+x+offset));}}return {top:ceiling+halfHeight,bottom:floor-halfHeight};}
function stopAtTerrain(body,halfWidth=24,halfHeight=24){const limits=surfaceBounds(body.x,halfWidth,halfHeight),old=body.y;body.y=clamp(body.y,limits.top,limits.bottom);return body.y!==old;}
function constrainPlayerTerrain(){const height=65*images.zaku.sh/images.zaku.sw;if(stopAtTerrain(player,25,height/2)&&moveTarget)moveTarget.y=player.y;}

