function damageCover(cover,damage){if(!cover||cover.hp<=0)return;cover.hp=Math.max(0,cover.hp-damage);cover.flash=.12;for(let i=0;i<3;i++)particles.push({x:cover.x+rand(-40,40),y:cover.y+rand(-50,50),vx:rand(-90,90),vy:rand(-70,80),life:.6,color:'#aaa18b',r:5});if(cover.hp===0){score+=150;explode(cover.x,cover.y,'#b1a489',20,'silent');for(let i=0;i<14;i++)particles.push({x:cover.x+rand(-48,48),y:cover.y+rand(-70,65),vx:rand(-150,150),vy:rand(-100,100),life:1.2,color:'#8b8372',r:rand(4,10)});groundNotice('遮蔽物崩壊 — ザクが露出',2);}}
