 const schedule=[48,64];if(m.coverIndex<2&&time>=schedule[m.coverIndex]&&time<79){const x=W+150,choices=Array.from({length:10},(_,i)=>i).filter(i=>i!==m.lastCoverArt),artIndex=choices[Math.floor(Math.random()*choices.length)],cover={x,y:terrain(scroll+x)-90,hp:8,max:8,flash:0,artIndex};m.lastCoverArt=artIndex;m.covers.push(cover);enemies.push(groundZaku(x,cover.y,{cover,shot:2.5}));m.coverIndex++;}
