// Same eight-second slots and normal-Zaku durability/fire interval; vary approach and lanes.
function spawnGroundWave(group){
 if(time>=80)return;
 const patterns=['line','cross','feint','flank','weave','cross','breather','flank','weave','feint'];
 const pattern=patterns[group%patterns.length];
 if(pattern==='breather'||enemies.filter(e=>e.hp>0&&!e.bossUnit).length>=9)return;
 const count=group===9?2:3,base=rand(210,360);
 if(groundMission.messageUntil<=time&&['cross','flank','feint'].includes(pattern))groundNotice(pattern==='cross'?'上下から接近 — 進路に注意':pattern==='flank'?'後方から敵機接近':'敵機が射撃位置へ接近',2.2);
 for(let i=0;i<count;i++){
  const back=pattern==='flank'&&i===2;
  const y=pattern==='cross'?(i%2?H-205:190):clamp(base+(i-1)*90,170,H-170);
  enemies.push(groundZaku(back?-70:W+80+i*135,y,{
   phase:group,red:i===count-1&&group%3!==2,shot:2+i*.8,
   formationSpeed:105,formationPhase:i*.35,
   ...(pattern==='line'?{}:{groundTactic:pattern,tacticStartY:y,tacticEndY:i%2?190:H-205,tacticClock:0,tacticPhase:'enter',pursuit:back,formationSpeed:back?170:145})
  }));
 }
}
function updateGroundTactic(e,dt){
 if(e.groundTactic==='feint'){
  if(e.tacticPhase==='enter'){e.x-=185*dt;if(e.x<=W-260){e.tacticPhase='aim';e.tacticClock=1.15;e.shot=Math.min(e.shot,.25);}}
  else if(e.tacticPhase==='aim'){e.tacticClock-=dt;if(e.tacticClock<=0){e.tacticPhase='back';e.tacticClock=.65;}}
  else if(e.tacticPhase==='back'){e.x+=120*dt;e.retreat=.1;e.tacticClock-=dt;if(e.tacticClock<=0)e.tacticPhase='exit';}
  else e.x-=225*dt;
 }else e.x+=(e.pursuit?1:-1)*e.formationSpeed*dt;
 if(e.groundTactic==='cross'){
  const t=clamp((e.age-.7)/4.3,0,1),p=t*t*(3-2*t);e.y=e.tacticStartY+(e.tacticEndY-e.tacticStartY)*p;
 }else if(e.groundTactic==='weave')e.y=e.tacticStartY+Math.sin(e.age*1.7+e.formationPhase)*65;
 else e.y=e.tacticStartY+Math.sin(e.age*.9+e.formationPhase)*18;
}
function hawkDashProtected(e){return !!e?.hawk&&e.hawkMode==='dash';}
function updateHawkZaku(e,dt){
 if(e.hawkMode==='hide'){
  const cover=e.ambushCover;e.hawkClock-=dt;
  if(!cover||cover.hp<=0){e.ambushCover=null;e.hawkMode='windup';e.hawkClock=.1;e.hawkTarget={x:player.x,y:player.y};e.pursuit=player.x>e.x;return;}
  const direction=player.x<cover.x?-1:1,progress=clamp(1-e.hawkClock/.45,0,1);
  e.x=cover.x+direction*100*progress;e.y=cover.y;
  if(e.hawkClock<=0){e.ambushCover=null;e.hawkMode='windup';e.hawkClock=.1;e.hawkTarget={x:player.x,y:player.y};e.pursuit=player.x>e.x;}
 }else if(e.hawkMode==='enter'){
  e.x+=(e.hawkEntry==='left'?1:-1)*340*dt;
  if(e.hawkEntry==='left'?e.x>85:e.x<W-95){e.hawkMode='windup';e.hawkClock=.1;e.hawkTarget={x:player.x,y:player.y};e.pursuit=player.x>e.x;}
 }else if(e.hawkMode==='windup'){
  e.hawkClock-=dt;
  if(e.hawkClock<=0){const dx=e.hawkTarget.x-e.x,dy=e.hawkTarget.y-e.y,a=Math.atan2(dy,dx);e.hawkVx=Math.cos(a)*720;e.hawkVy=Math.sin(a)*720;e.hawkMode='dash';e.hawkClock=clamp(Math.hypot(dx,dy)/720+.12,.45,1.7);e.hawkStrikes=(e.hawkStrikes||0)+1;}
 }else if(e.hawkMode==='dash'){
  e.x+=e.hawkVx*dt;e.y+=e.hawkVy*dt;e.hawkClock-=dt;
  if(Math.hypot(e.x-player.x,e.y-player.y)<63)hit();
  if(e.hawkClock<=0){e.hawkMode='recover';e.hawkClock=.7;}
 }else if(e.hawkMode==='recover'){
  e.hawkClock-=dt;
  if(e.hawkClock<=0){if((e.hawkStrikes||0)<2&&e.x>45&&e.x<W+30){e.hawkMode='windup';e.hawkClock=.1;e.hawkTarget={x:player.x,y:player.y};e.pursuit=player.x>e.x;}else e.hawkMode='exit';}
 }else e.x-=260*dt;
}

function updateGroundHawkRush(m){
 if(time<56||time>=76||(m.hawkRushIndex||0)>=8)return;
 const index=m.hawkRushIndex||0;
 if(time<56+index*2.2||enemies.filter(e=>e.hawk&&e.hp>0&&e.hawkMode!=='exit').length>=4)return;
 const left=index%2===1,high=index%4<2;
 const available=m.covers.filter(c=>c.urban&&c.hp>0&&c.x>240&&c.x<W-95&&!enemies.some(e=>e.hp>0&&e.ambushCover===c));
 const cover=available.length?available[index%available.length]:null;
 enemies.push(groundZaku(cover?cover.x:left?-70:W+100,cover?cover.y:high?175:H-175,{hp:4,hawk:true,hawkMode:cover?'hide':'enter',hawkClock:cover?.45:0,ambushCover:cover,hawkEntry:left?'left':'right',pursuit:left,hawkRush:true,shot:999}));
 m.hawkRushIndex=index+1;
 if(index===0)groundNotice('市街地の伏兵 — 建物の陰から突進',3);
 else groundNotice(cover?'建物の陰に突進機！':(left?'左':'右')+(high?'上':'下')+'から突進機接近',1.2);
}

// Scrolling city obstacles share their drawn 130x170 footprint with collision.
function updateGroundUrban(m){
 const index=m.urbanIndex||0;
 if(index>=11||time<44+index*2.8||time>=75)return;
 const artIndex=(index*3+2)%10;
 m.covers.push({x:W+140,y:index%2?450:250,hp:80,max:80,flash:0,artIndex,urban:true});
 m.urbanIndex=index+1;
 if(index===0)groundNotice('市街地へ — 建物の隙間を抜けろ',3);
}
function constrainUrbanBuildings(body,halfWidth=25,halfHeight=33){
 if(!groundStage||time>=90)return false;let blocked=false;
 for(const c of groundMission.covers){
  if(!c.urban||c.hp<=0||body.hawkMode==='hide'&&body.ambushCover===c)continue;
  const w=65+halfWidth,h=85+halfHeight;
  if(Math.abs(body.x-c.x)>=w||Math.abs(body.y-c.y)>=h)continue;
  const limits=surfaceBounds(body.x,halfWidth,halfHeight);
  const choices=[{x:c.x-w-.1,y:body.y},{x:c.x+w+.1,y:body.y},{x:body.x,y:c.y-h-.1},{x:body.x,y:c.y+h+.1}]
   .filter(p=>p.y>=limits.top&&p.y<=limits.bottom&&(body!==player||p.x>=40&&p.x<=W-45));
  choices.sort((a,b)=>Math.hypot(a.x-body.x,a.y-body.y)-Math.hypot(b.x-body.x,b.y-body.y));
  const p=choices[0];if(!p)continue;
  if(body===player&&moveTarget){if(p.x!==body.x)moveTarget.x=p.x;if(p.y!==body.y)moveTarget.y=p.y;}
  body.x=p.x;body.y=p.y;blocked=true;
 }
 return blocked;
}
function urbanBuildingBlocksBullet(b){
 if(!groundStage||!groundMission.covers.some(c=>c.urban&&c.hp>0&&Math.abs(b.x-c.x)<65+(b.r||0)&&Math.abs(b.y-c.y)<85+(b.r||0)))return false;
 if(b.type==='legMissile'||b.type==='grenade')explode(b.x,b.y,'#ffc17a',8,'silent');
 b.x=-100;return true;
}

function launchLegMissile(e){e.missileFlash=.3;const sx=e.x-12,sy=e.y+30,target={x:player.x,y:player.y},side=target.y<sy?-1:1;bullets.push({x:sx,y:sy,vx:0,vy:0,r:7,type:'legMissile',age:0,duration:2.4,start:{x:sx,y:sy},c1:{x:sx-25,y:Math.min(sy+95,terrainFloor()-30)},c2:{x:target.x+180,y:clamp(target.y+side*155,65,terrainFloor()-45)},target,trail:[]});}
function updateLegMissile(b,dt){b.age+=dt;const t=clamp(b.age/b.duration,0,1),u=1-t;b.trail.push({x:b.x,y:b.y});if(b.trail.length>10)b.trail.shift();const x=u*u*u*b.start.x+3*u*u*t*b.c1.x+3*u*t*t*b.c2.x+t*t*t*b.target.x,y=u*u*u*b.start.y+3*u*u*t*b.c1.y+3*u*t*t*b.c2.y+t*t*t*b.target.y;b.angle=Math.atan2(y-b.y,x-b.x);b.x=x;b.y=y;if(t>=1){explode(b.x,b.y,'#ffb36b',7,'silent');b.x=-100;}}
