function spawnWave(){const group=wave++,base=rand(150,520),red=group%2===0;if(groundStage){spawnGroundWave(group);return;}for(let i=0;i<(groundStage?3:5);i++)enemies.push({x:W+55+i*80,y:base,base,age:-i*.3,hp:2,type:'zaku',red:red&&i===4,phase:group%3,shot:rand(6,7.5),size:65,canRetreat:Math.random()<.35,independent:false,soloGoal:0,soloClock:0,retreat:0,nextRetreat:rand(1.5,3.5)});}
const guardFormations=[{name:'横一列',points:[[-60,-100],[0,-100],[60,-100],[120,-100]]},{name:'四角',points:[[80,-135],[140,-135],[80,-65],[140,-65]]},{name:'ひし形',points:[[80,-165],[20,-105],[140,-105],[80,-45]]}];
function createGuardFormation(index=Math.floor(Math.random()*guardFormations.length)){const f=guardFormations[index];return {formation:f.name,guards:f.points.map(([x,y],i)=>({x,y,hp:3,max:3,shot:2+i*.65,flash:0}))};}
function guardPosition(g){return {x:boss.x+g.x,y:boss.y+g.y};}
function meleePosition(m){return m.kind==='guard'?guardPosition(m.target):m.target;}
function meleeContactSafe(target){return player.melee?.target===target&&player.melee.age<.42;}
function startMelee(){if(player.javelin)return startJavelin();if(launch||player.dying>0||player.melee||player.meleeCooldown>0)return false;const candidates=[];if(boss&&!boss.dying&&boss.x<=900)for(const g of boss.guards||[])if(g.hp>0)candidates.push({kind:'guard',target:g});for(const e of enemies)if(e.hp>0)candidates.push({kind:'enemy',target:e});if(charZaku&&charZaku.hp>0&&charZaku.mode!=='retreat')candidates.push({kind:'char',target:charZaku});const close=candidates.filter(m=>{const p=meleePosition(m);return p.x-player.x>=-10&&p.x-player.x<=95&&Math.abs(p.y-player.y)<=48;}).sort((a,b)=>{const p=meleePosition(a),q=meleePosition(b);return Math.hypot(p.x-player.x,p.y-player.y)-Math.hypot(q.x-player.x,q.y-player.y)});if(!close.length)return false;player.melee={...close[0],age:0,hit:false};player.meleeCooldown=.65;return true;}
function enemyDropsItem(e){if(e.red)return !boss||Math.random()<.4;return e.type==='turret'&&Math.random()<(boss?.15:.6);}
function dropBossItem(x,y){if(Math.random()<.65)capsules.push({x,y,age:0});}
function meleeStrike(m){if(m.javelin){strikeJavelin(m);return;}const p=meleePosition(m);if(m.target.hp<=0||p.x-player.x< -20||p.x-player.x>110||Math.abs(p.y-player.y)>60)return;if(!muted&&!playSfx('saberSwing'))tone(900,.09,'triangle',.04);if(m.kind==='enemy'&&(denimProtected(m.target)||m.target.recoveryShield||hawkDashProtected(m.target)))return;if(m.kind==='enemy'&&m.target.geneRetreat){killRetreatingGene(m.target);return;}if(m.kind==='enemy'&&(m.target.cover?.hp>0||m.target.ambushCover?.hp>0)){damageCover(m.target.cover||m.target.ambushCover,3);return}if(m.kind==='char'){hitChar({x:p.x,y:p.y,w:1,h:1,damage:3,life:1});return}const strikeDamage=stageNumber===3?stageThree.filterDamage(m.target,3,{x:player.x,y:player.y,r:110}):3;m.target.hp=Math.max(0,m.target.hp-strikeDamage);if(m.target.hp>0)return;if(stageNumber===3&&m.kind==='enemy'&&stageThree.onKilled(m.target))return;if(m.kind==='enemy'&&beginGeneRecovery(m.target))return;if(m.kind==='guard'){score+=300;destroySuit('zakuShield',p.x,p.y);materialDrop(p.x,p.y,2);}else{const e=m.target;score+=e.type==='turret'?200:100;if(e.type==='zaku')destroyEnemySuit(e);else explode(e.x,e.y,'#a6efbe');enemyReward(e);}}
function updateMelee(dt){player.meleeCooldown=Math.max(0,(player.meleeCooldown||0)-dt);if(player.dying>0){player.melee=null;return}if(player.melee){const m=player.melee;m.age+=dt;if(!m.hit&&m.age>=.12){m.hit=true;meleeStrike(m)}if(m.age>=.42)player.melee=null;}else startMelee();}
function updateGuards(dt){if(!boss||boss.dying)return;for(const g of boss.guards||[]){g.flash=Math.max(0,g.flash-dt);if(g.hp<=0)continue;g.shot-=dt;const p=guardPosition(g);if(g.shot<=0&&boss.x<=900){g.shot=4;aimed(p.x-26,p.y,160)}if(Math.hypot(p.x-player.x,p.y-player.y)<36&&!meleeContactSafe(g))hit();}}
function drawGuards(){if(!boss||boss.dying)return;for(const g of boss.guards||[]){if(g.hp<=0)continue;const p=guardPosition(g);sprite('zakuShield',p.x,p.y,65,g.flash>0?.55:1);ctx.fillStyle='#253627';ctx.fillRect(p.x-22,p.y-38,44,3);ctx.fillStyle='#b8e889';ctx.fillRect(p.x-22,p.y-38,44*g.hp/g.max,3);}}
function playerCombatSuit(){if(player.melee?.javelin){const m=player.melee;return 'javelinArt'+(m.age<.12||m.age>=.38?0:m.direction<0?3:m.age<.3?1:2);}return player.melee?(player.melee.age<.12?'gundamSaberReady':'gundamSaberSlash'):player.backBoost>0?'gundamBack':player.missile&&lv('bazookaRapid')?'gundamDual':player.missile||player.double?'gundamBazooka':player.laser?'gundam':'gundamUnarmed';}

function shoot(x,y,option=false,forceVulcan=false){const laser=player.laser&&!forceVulcan,count=!laser&&player.spread?3+2*lv('spread'):1;for(let i=0;i<count;i++){const a=(i-(count-1)/2)*.12;shots.push({x:x+28,y:y+(laser?0:-18),vx:(laser?950:780)*Math.cos(a),vy:laser?0:780*Math.sin(a),w:laser?64:12,h:laser?5+4*lv('rifleWidth'):3,damage:laser?2*(1+.2*lv('riflePower')):1,kind:laser?'laser':'vulcan',life:2,range:laser?W:360,travel:0,hitTargets:new Set()});}if(!option&&!muted){if(laser){if(time-lastRifleSound>=.26){lastRifleSound=time;if(!playSfx('rifleShot'))tone(700,.035,'triangle',.012)}}else if(!playSfx('vulcanShot'))tone(950,.035,'triangle',.012);}}
function fireVolley(){if(state!=='playing'||launch||groundBossIntro?.active||player.dying>0)return;if(player.melee||startMelee())return;if(player.laser){shoot(player.x,player.y);if(lv('vulcanMix'))shoot(player.x,player.y,true,true);}else if(!player.missile||lv('vulcanMix'))shoot(player.x,player.y);if(!player.laser&&player.missile&&missileClock<=0){missileClock=lv('bazookaRapid')?.35:.7;for(const direction of [-1,1])shots.push({x:player.x+28,y:player.y+direction*18,vx:340,vy:direction*240,w:16,h:7,damage:3,kind:'bazooka',life:3,range:380,travel:0});}fireClock=.14;}
function destroyEnemySuit(e){const finalGene=!!groundStage&&e.bossUnit&&!e.chief&&e.recoveryUsed;if(finalGene&&!muted)playSfx('geneDeathVoice');destroySuit(e.retreat>0?'zakuBack':'zaku',e.x,e.y,'#ffaa64',finalGene?1.3:.48,finalGene);if(finalGene){const wreck=wrecks[wrecks.length-1];wreck.explosionDuration=4;wreck.geneExplosion=true;wreck.openBreach=true;}}
function disableGene(e){if(e.geneDisabled)return true;e.hp=0;e.geneDisabled=true;e.geneRecovering=false;e.recoveryShield=true;e.conversationHold=true;e.bossMode='disabled';e.burstLeft=0;boss.exchange=null;boss.geneTauntAt=null;boss.geneExitScene={phase:'blast',elapsed:0};explode(e.x+10,e.y-8,'#ffb274',10,'silent');if(!muted)playSfx('damage',true);return true;}
function killRetreatingGene(gene){if(!gene.geneRetreat||gene.hp<=0)return;gene.hp=0;gene.geneRetreat=false;gene.geneDisabled=false;gene.recoveryShield=false;gene.geneKilled=true;boss.geneExitScene=null;score+=100;destroyEnemySuit(gene);for(const offset of [-18,18])capsules.push({x:gene.x+offset,y:gene.y,age:0});const denim=boss.units.find(e=>e.chief);if(denim?.hp>0){denim.furyMode=true;denim.conversationHold=true;denim.conversationGoal=null;denim.bossMode='fury-wait';denim.shielding=false;boss.denimFury={phase:'blast',elapsed:0};}}
function startDenimFuryCombat(){const denim=boss?.kind==='zakuPair'&&boss.units.find(e=>e.chief);if(!denim?.furyMode||denim.hp<=0)return;denim.conversationHold=false;denim.bossMode='windup';denim.bossClock=.6;denim.slashTarget={x:player.x,y:player.y};boss.denimFury={phase:'combat',elapsed:0};}
function beginGeneRetreat(){const gene=boss?.kind==='zakuPair'&&boss.units.find(e=>!e.chief);if(!gene?.geneDisabled||gene.geneRetreat)return;gene.geneRetreat=true;gene.hp=3;gene.max=3;gene.recoveryShield=false;gene.conversationHold=false;gene.bossMode='retreat';boss.geneExitScene={phase:'retreat',elapsed:0};}
// Dialogue completion follows media playback, never the time spent downloading it.
// A bounded no-progress watchdog also handles a play() Promise that never settles.
function finishDialogueCue(name){
 const media=sfxPool[name]?.[0];media?.pause();if(requestedVoiceMedia===media)requestedVoiceMedia=null;
 if(voicePending?.media===media){voiceEpoch++;voicePending=null;}
 voiceRemaining=0;
}
function dialogueCueFinished(scene,name,duration,dt){
 const media=sfxPool[name]?.[0];
 const cue=scene.voiceCue?.name===name?scene.voiceCue:(scene.voiceCue={name,elapsed:0,position:0,stalled:0,pendingAge:0,retries:0});
 cue.elapsed+=dt;
 if(muted||!media||media.error){if(cue.elapsed<duration)return false;finishDialogueCue(name);return true;}
 const total=Number.isFinite(media.duration)&&media.duration>0?media.duration:duration;
 const position=Number.isFinite(media.currentTime)?media.currentTime:0;
 if(media.ended||position>=total-.015){finishDialogueCue(name);return true;}
 if(position>cue.position+.002){cue.stalled=0;cue.position=position;}else cue.stalled+=dt;
 voiceRemaining=Math.max(voiceRemaining,total-position,.2);
 if(voicePending?.media===media){
  cue.pendingAge+=dt;
  if(voicePending.attempts>=3&&!voicePending.inFlight){voiceEpoch++;voicePending=null;cue.retries=3;}
  else if(voicePending.inFlight&&cue.pendingAge>=2){voiceEpoch++;voicePending=null;cue.pendingAge=0;}
 }else cue.pendingAge=0;
 if(media.paused&&!voicePending&&cue.retries<3){cue.retries++;requestCharVoice(name,true);}
 // No progress for 12 active seconds: skip an unavailable clip and release the scene.
 // Pauses do not advance this timer; real playback progress resets it.
 if(cue.stalled>=12&&cue.elapsed>=total){finishDialogueCue(name);return true;}
 return false;
}

function updateGeneExit(dt){
 const scene=boss?.geneExitScene;if(!scene)return;scene.elapsed+=dt;
 if(scene.phase==='blast'){
  if(scene.elapsed<.6)return;
  const prior=sfxPool.geneTauntVoice?.[0];
  if(boss.geneTauntPlayed&&prior&&!prior.ended&&(prior.currentTime||0)<4){
   scene.waitCue??={};if(!dialogueCueFinished(scene.waitCue,'geneTauntVoice',4,dt))return;
  }
  scene.phase='reaction';scene.elapsed=0;if(!muted)playSfx('denimReactionVoice');return;
 }
 if(!['reaction','jump'].includes(scene.phase))return;
 const name=scene.phase==='reaction'?'denimReactionVoice':'geneJumpVoice',duration=scene.phase==='reaction'?5.2:10;
 if(!dialogueCueFinished(scene,name,duration,dt))return;
 if(scene.phase==='reaction'){scene.phase='jump';scene.elapsed=0;if(!muted)playSfx('geneJumpVoice');}else beginGeneRetreat();
}

function beginGeneRecovery(e){if(!groundStage||!e.bossUnit||e.chief||boss?.kind!=='zakuPair')return false;if(e.recoveryUsed)return disableGene(e);e.hp=0;e.recoveryUsed=true;summonBossTruck();e.geneRecovering=true;e.recoveryShield=true;e.conversationHold=true;e.bossMode='conversation';e.burstLeft=0;boss.geneVoicePlayed=true;boss.exchange={phase:'gene',elapsed:0};if(!muted)playSfx('geneVoice');return true;}
function updateDenimFury(dt){
 const scene=boss?.denimFury;if(!scene||scene.phase==='combat')return;scene.elapsed+=dt;
 if(scene.phase==='blast'){
  if(scene.elapsed>=5.3&&!explosionSprites.some(e=>e.breachBlast)){scene.phase='breach';scene.elapsed=0;startBreachScene();}return;
 }
 if(scene.phase==='breach'){
  if(colonyBreach?.cinematic)return;
  scene.phase='line';scene.elapsed=0;if(!muted)playSfx('denimFuryVoice');return;
 }
 if(dialogueCueFinished(scene,'denimFuryVoice',4.5,dt))startDenimFuryCombat();
}

function updateBossExchange(dt){if(!groundStage||boss?.kind!=='zakuPair')return;updateDenimFury(dt);const gene=boss.units.find(e=>!e.chief),denim=boss.units.find(e=>e.chief);let exchange=boss.exchange;if(gene?.geneDisabled){updateGeneExit(dt);return;}
 const release=()=>{for(const e of boss.units){e.conversationHold=false;e.recoveryShield=false;e.conversationGoal=null;e.conversationArrived=false;if(e.bossMode==='conversation')e.bossMode=null;e.shot=Math.max(1,e.shot);}boss.exchange=null;};
 if(!gene||gene.hp<=0&&!gene.geneRecovering||!denim||denim.hp<=0){if(exchange){release();voiceEpoch++;voicePending=null;voiceRemaining=0;for(const key of ['geneVoice','denimVoice','geneRallyVoice'])for(const media of sfxPool[key]||[])media.pause();}return;}
 if(!exchange){if(boss.geneTauntAt!=null&&!boss.geneTauntPlayed&&time>=boss.geneTauntAt){boss.geneTauntPlayed=true;if(!muted)playSfx('geneTauntVoice');}return;}exchange.elapsed+=dt;
 if(exchange.phase==='approach'){denim.conversationGoal={x:gene.x,y:gene.y};if(denim.conversationArrived){gene.hp=gene.max;gene.geneRecovering=false;exchange.phase='denim';exchange.elapsed=0;if(!muted)playSfx('denimVoice');}return;}
 const name=exchange.phase==='gene'?'geneVoice':exchange.phase==='rally'?'geneRallyVoice':'denimVoice',duration=exchange.phase==='gene'?5:3,media=sfxPool[name]?.[0];
 if(!dialogueCueFinished(exchange,name,duration,dt))return;
 if(exchange.phase==='gene'){exchange.phase='approach';exchange.elapsed=0;gene.conversationHold=true;gene.bossMode='conversation';gene.burstLeft=0;denim.bossMode='conversation';denim.burstLeft=0;denim.conversationGoal={x:gene.x,y:gene.y};denim.conversationArrived=false;}else if(exchange.phase==='denim'){exchange.phase='rally';exchange.elapsed=0;if(!muted)playSfx('geneRallyVoice');}else{for(const e of boss.units){e.enraged=true;e.singleShotClock=.25;e.shot=.4;}boss.geneTauntAt=time+3;boss.geneTauntPlayed=false;release();}
}
function damageEnemy(e,damage,source){if(stageNumber===3){damage=stageThree.filterDamage(e,damage,source||{x:player.x,y:player.y,r:110});if(damage<=0)return;}if(e.hp<=0||e.geneRetreat||e.recoveryShield||hawkDashProtected(e)||denimProtected(e)||e.cover?.hp>0||e.ambushCover?.hp>0||e.bossUnit&&e.shielding)return;e.hp=Math.max(0,e.hp-damage);if(e.hp>0)return;if(stageNumber===3&&stageThree.onKilled(e))return;if(beginGeneRecovery(e))return;score+=e.type==='turret'?200:100;if(e.type==='zaku')destroyEnemySuit(e);else explode(e.x,e.y,e.red?'#ff7866':'#a6efbe');enemyReward(e);}
function detonate(s){if(s.burst)return;s.burst=true;s.life=0;explode(s.x,s.y,'#ffb665',20,'silent');const radius=s.blastRadius||65;for(const e of enemies)if(e.hp>0&&Math.hypot(e.x-s.x,e.y-s.y)<radius+e.size*.3){if(e.cover?.hp>0||e.ambushCover?.hp>0)damageCover(e.cover||e.ambushCover,s.damage);else damageEnemy(e,s.damage,{x:s.x,y:s.y,r:radius});}if(charZaku&&Math.hypot(charZaku.x-s.x,charZaku.y-s.y)<radius+28)hitChar({x:charZaku.x,y:charZaku.y,w:1,h:1,damage:s.damage,life:1});if(boss&&!groundStage&&stageNumber===2&&!boss.dying){for(const t of boss.turrets)if(t.hp>0&&Math.hypot(boss.x+t.x-s.x,boss.y+t.y-s.y)<radius+15){t.hp=Math.max(0,t.hp-s.damage);if(t.hp===0){score+=400;explode(boss.x+t.x,boss.y+t.y,'#ffb665',28);dropBossItem(boss.x+t.x,boss.y+t.y);}}if(!(boss.guards||[]).some(g=>g.hp>0)&&Math.hypot(boss.x+225-s.x,boss.y-78-s.y)<radius+25){boss.hp-=s.damage;if(boss.hp<=0)beginVictory();}}}
